<template><main class="container page-section"><p class="eyebrow">Library</p><h1 class="page-title">收藏</h1><div v-if="loading" class="empty">正在载入收藏…</div><div v-else-if="error" class="empty error-state" role="alert">{{error}}</div><div v-else-if="!items.length" class="empty">还没有收藏公开文章。</div><div v-else class="list"><article v-for="post in items" :key="post.id" class="card post"><RouterLink class="post-link" :to="`/posts/${post.slug}`"><img v-if="post.cover_image" :src="post.cover_image" :alt="post.cover_alt_text||''" /><div><small>{{post.username}} · {{date(post.published_at)}}</small><h2>{{post.title}}</h2><p>{{post.excerpt}}</p></div></RouterLink><button class="button button-secondary" type="button" :disabled="pending===post.id" @click="remove(post)">{{pending===post.id?'处理中…':'取消收藏'}}</button></article></div></main></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{RouterLink}from'vue-router';import http from'@/services/http';const items=ref<any[]>([]),loading=ref(true),error=ref(''),pending=ref<number|null>(null),date=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v));async function load(){try{items.value=(await http.get('/api/bookmarks')).data.items||[]}catch(e:any){error.value=e.response?.data?.error?.message||'收藏暂时无法载入'}finally{loading.value=false}}async function remove(post:any){pending.value=post.id;try{await http.delete(`/api/posts/${post.id}/bookmark`);items.value=items.value.filter((item)=>item.id!==post.id)}catch(e:any){error.value=e.response?.data?.error?.message||'取消收藏失败'}finally{pending.value=null}}onMounted(load)</script>
<style scoped>.list{display:grid;gap:var(--space-3)}.post{display:flex;align-items:center;gap:var(--space-3);padding:var(--space-3)}.post-link{display:flex;align-items:center;gap:var(--space-3);min-width:0;flex:1;color:inherit;text-decoration:none}.post-link img{width:120px;aspect-ratio:16/9;object-fit:cover;border-radius:var(--radius-sm)}.post-link div{min-width:0}.post h2{font-size:1.15rem;margin:4px 0}.post p,small{color:var(--muted)}.empty{display:grid;justify-items:center;gap:var(--space-2);padding:var(--space-6);color:var(--muted)}.error-state{border:1px solid var(--border);border-radius:var(--radius)}@media(max-width:560px){.post{align-items:stretch;flex-direction:column}.post-link{align-items:start}.post-link img{width:96px}.post .button{width:100%}}
</style>
